        "Απαντάει στην ερώτηση πού • — μετακίνηση σε συγκεκριμένο μέρος ή επιφάνεια.",
        "Σε μια οριζόντια επιφάνεια, το auf den χρησιμοποιείται συχνά αντί για aufs.",
