        "Baden μπορεί επίσης να σημαίνει μπάνιο.",
        "Όταν δίνεται έμφαση στις ίδιες τις κολυμβητικές κινήσεις ή στο άθλημα, το schwimmen χρησιμοποιείται συχνότερα στα γερμανικά."
