        "Πλήρης μορφή: σε das (Κατηγορούμενο).",
        "Χρησιμοποιείται με ουδέτερα ουσιαστικά όταν απαντά στην ερώτηση πού • — κίνηση προς τα μέσα.",
        "Συχνά με ρήματα: gehen, fahren, kommen, legen, stecken.",
