        "Αυτό δεν είναι το ίδιο με το ob, το οποίο εισάγει μια έμμεση ερώτηση.",
        "Στις συνομιλίες, το oder μπορεί επίσης να βρίσκεται στο τέλος της πρότασης: Du kommst, oder?"
